{
  "tools": [
    {
      "service": "github",
      "tool_id": "github.get_pull_request",
      "name": "Get Pull Request",
      "description": "Get a specific pull request by number",
      "riskLevel": "low",
      "params": {
        "type": "object",
        "required": [
          "owner",
          "repo",
          "pullNumber"
        ],
        "properties": {
          "owner": {
            "type": "string"
          },
          "repo": {
            "type": "string"
          },
          "pullNumber": {
            "type": "integer"
          }
        }
      }
    },
    {
      "service": "github",
      "tool_id": "github.create_comment",
      "name": "Create Comment",
      "description": "Create a comment on an issue or pull request",
      "riskLevel": "medium",
      "params": {
        "type": "object",
        "required": [
          "owner",
          "repo",
          "issueNumber",
          "body"
        ],
        "properties": {
          "owner": {
            "type": "string"
          },
          "repo": {
            "type": "string"
          },
          "issueNumber": {
            "type": "integer"
          },
          "body": {
            "type": "string"
          }
        }
      }
    },
    {
      "service": "github",
      "tool_id": "github.list_pull_requests",
      "name": "List Pull Requests",
      "description": "List pull requests for a repository with optional state filter",
      "riskLevel": "low",
      "params": {
        "type": "object",
        "required": [
          "owner",
          "repo"
        ],
        "properties": {
          "owner": {
            "type": "string",
            "description": "Repository owner"
          },
          "repo": {
            "type": "string",
            "description": "Repository name"
          },
          "state": {
            "anyOf": [
              {
                "type": "string",
                "const": "open"
              },
              {
                "type": "string",
                "const": "closed"
              },
              {
                "type": "string",
                "const": "all"
              }
            ],
            "description": "PR state filter (default: open)"
          },
          "limit": {
            "type": "integer",
            "minimum": 1,
            "maximum": 100,
            "description": "Max results (default: 30, max 100)"
          }
        }
      }
    },
    {
      "service": "github",
      "tool_id": "github.inspect_pull_request",
      "name": "Inspect Pull Request",
      "description": "Get detailed PR info including files changed, review comments, check status, and who is already requested to review or assigned. Set includePatch to read the diff, and pathPrefixes to scope to a folder; `matched_file_count` is a scalar a workflow if-node can compare against a number.",
      "riskLevel": "low",
      "params": {
        "type": "object",
        "required": [
          "owner",
          "repo",
          "pullNumber"
        ],
        "properties": {
          "owner": {
            "type": "string",
            "description": "Repository owner"
          },
          "repo": {
            "type": "string",
            "description": "Repository name"
          },
          "pullNumber": {
            "type": "integer",
            "description": "Pull request number"
          },
          "filesLimit": {
            "type": "integer",
            "minimum": 1,
            "maximum": 300,
            "description": "Max files (default: 100)"
          },
          "commentsLimit": {
            "type": "integer",
            "minimum": 1,
            "maximum": 300,
            "description": "Max review comments (default: 100)"
          },
          "includePatch": {
            "type": "boolean",
            "description": "Include each file's unified diff in the `patch` field (default: false). Needed to review the code itself; costs prompt space."
          },
          "patchBytesLimit": {
            "type": "integer",
            "minimum": 1024,
            "maximum": 1048576,
            "description": "Total byte budget for all patches (default: 65536). Files are filled in order. Every cut is reported in `patch_truncated`, `patch_omitted`, and `patch_summary`."
          },
          "pathPrefixes": {
            "type": "array",
            "items": {
              "type": "string"
            },
            "description": "Keep only files whose path starts with one of these prefixes. End a prefix with \"/\" to scope to a folder exactly — \"source/rest\" also matches \"source/restore.go\". The count of kept files is returned as `matched_file_count`."
          }
        }
      }
    },
    {
      "service": "github",
      "tool_id": "github.create_review",
      "name": "Create Pull Request Review",
      "description": "Submit a review on a pull request, with an optional set of inline comments anchored to diff lines. Omit event to leave the review pending. Set updateExisting to replace this action's previous review instead of adding another one.",
      "riskLevel": "medium",
      "params": {
        "type": "object",
        "required": [
          "owner",
          "repo",
          "pullNumber"
        ],
        "properties": {
          "owner": {
            "type": "string",
            "description": "Repository owner"
          },
          "repo": {
            "type": "string",
            "description": "Repository name"
          },
          "pullNumber": {
            "type": "integer",
            "description": "Pull request number"
          },
          "body": {
            "type": "string",
            "description": "Review summary in markdown. GitHub requires it when event is COMMENT or REQUEST_CHANGES."
          },
          "event": {
            "anyOf": [
              {
                "type": "string",
                "const": "COMMENT"
              },
              {
                "type": "string",
                "const": "REQUEST_CHANGES"
              }
            ],
            "description": "Review verdict. Omit it to leave the review PENDING, which stages the comments until someone submits them. APPROVE is not available here: an approving review can satisfy branch protection, which is a merge authorization and not a review remark."
          },
          "commitId": {
            "type": "string",
            "description": "SHA the review applies to (defaults to the head commit at post time). Pass the SHA the diff was read at — on a busy pull request a new push can land between the two calls, which moves the line anchors."
          },
          "comments": {
            "type": "array",
            "items": {
              "type": "object",
              "required": [
                "path",
                "body"
              ],
              "properties": {
                "path": {
                  "type": "string",
                  "description": "File path, relative to the repository root"
                },
                "body": {
                  "type": "string",
                  "description": "Comment text in markdown"
                },
                "line": {
                  "type": "integer",
                  "description": "Line number in the file, as it appears in the pull request diff. A line that is not in the diff makes GitHub reject the whole review."
                },
                "side": {
                  "anyOf": [
                    {
                      "type": "string",
                      "const": "LEFT"
                    },
                    {
                      "type": "string",
                      "const": "RIGHT"
                    }
                  ],
                  "description": "LEFT for a removed line, RIGHT for an added or unchanged line (default: RIGHT)"
                },
                "startLine": {
                  "type": "integer",
                  "description": "First line of a multi-line comment. `line` is the last."
                },
                "startSide": {
                  "anyOf": [
                    {
                      "type": "string",
                      "const": "LEFT"
                    },
                    {
                      "type": "string",
                      "const": "RIGHT"
                    }
                  ]
                },
                "position": {
                  "type": "integer",
                  "description": "Legacy anchor: offset from the first @@ hunk header. Prefer line. It cannot be combined with line, side, startLine, or startSide."
                }
              }
            },
            "description": "Inline comments, anchored to a file and a line of the diff"
          },
          "updateExisting": {
            "type": "boolean",
            "description": "Replace the body of this action's previous review on the pull request instead of adding another one (default: false). Use it for a re-review, so repeated runs do not stack duplicates. It cannot carry inline comments — GitHub's review-update endpoint changes the summary body only."
          },
          "updateKey": {
            "type": "string",
            "description": "Names the review stream `updateExisting` replaces (default: \"default\"). Give two review workflows on one repository different keys, so each updates only its own review."
          }
        }
      }
    },
    {
      "service": "github",
      "tool_id": "github.update_pull_request",
      "name": "Update Pull Request",
      "description": "Update a pull request title, body, state, labels, or assignees",
      "riskLevel": "medium",
      "params": {
        "type": "object",
        "required": [
          "owner",
          "repo",
          "pullNumber"
        ],
        "properties": {
          "owner": {
            "type": "string",
            "description": "Repository owner"
          },
          "repo": {
            "type": "string",
            "description": "Repository name"
          },
          "pullNumber": {
            "type": "integer",
            "description": "Pull request number"
          },
          "title": {
            "type": "string",
            "description": "New title"
          },
          "body": {
            "type": "string",
            "description": "New body (markdown)"
          },
          "state": {
            "anyOf": [
              {
                "type": "string",
                "const": "open"
              },
              {
                "type": "string",
                "const": "closed"
              }
            ],
            "description": "Set PR state"
          },
          "labels": {
            "type": "array",
            "items": {
              "type": "string"
            },
            "description": "Labels to set (replaces existing)"
          },
          "assignees": {
            "type": "array",
            "items": {
              "type": "string"
            },
            "description": "Assignee usernames (replaces existing)"
          }
        }
      }
    },
    {
      "service": "github",
      "tool_id": "github.create_pull_request",
      "name": "Create Pull Request",
      "description": "Create a new pull request",
      "riskLevel": "medium",
      "params": {
        "type": "object",
        "required": [
          "owner",
          "repo",
          "title",
          "head",
          "base"
        ],
        "properties": {
          "owner": {
            "type": "string",
            "description": "Repository owner"
          },
          "repo": {
            "type": "string",
            "description": "Repository name"
          },
          "title": {
            "type": "string",
            "description": "PR title"
          },
          "head": {
            "type": "string",
            "description": "Branch containing changes (or \"user:branch\" for cross-repo)"
          },
          "base": {
            "type": "string",
            "description": "Branch to merge into"
          },
          "body": {
            "type": "string",
            "description": "PR description (markdown)"
          },
          "draft": {
            "type": "boolean",
            "description": "Create as draft PR"
          }
        }
      }
    },
    {
      "service": "github",
      "tool_id": "github.merge_pull_request",
      "name": "Merge Pull Request",
      "description": "Merge a pull request",
      "riskLevel": "high",
      "params": {
        "type": "object",
        "required": [
          "owner",
