      "params": {
        "type": "object",
        "required": [
          "q"
        ],
        "properties": {
          "q": {
            "type": "string",
            "description": "Search query (supports qualifiers like \"repo:\", \"is:issue\", \"is:pr\", \"label:\", \"state:\")"
          },
          "sort": {
            "anyOf": [
              {
                "type": "string",
